/// <summary>Shapes one acted part into a sentence a voice can read: the writer's own words,
/// given a capital and an ending when they lack one.
/// <para>
/// THE CAPITAL IS NOT COSMETIC. <see cref="IsContinuation"/> reads a lone stop followed by a
/// lower-case letter as an abbreviation and refuses to cut there — so "…since the fords. she
/// sets down the cup." loses the FORDS' own sentence end, and the line before the gesture is
/// swallowed into the same bite with continuation prosody. Closing the gesture without lifting
/// it mends one end of the seam and opens the other.
/// </para></summary>
private static string AsNarration(string text)
{
    var t = Closed(text);
    if (t.Length == 0) return t;
    return char.IsLower(t[0]) ? char.ToUpperInvariant(t[0]) + t.Substring(1) : t;
}

