[Fact]
public void SpokenWithGestures_LiftsTheGestureSoTheSentenceBeforeItStillEnds()
{
    const string body = "The horses are spent and the men have not eaten since the fords. "
        + "*she sets down the cup* We should rest here until first light, whatever the marshal says.";
    Assert.Contains("fords. She sets down the cup.", SpeakableText.SpokenWithGestures(body));
    // Lower-cased, IsContinuation reads the fords' stop as an abbreviation and never cuts there.
    var bites = SpeakableText.BitesFor(body, includeGestures: true);
    Assert.EndsWith("fords.", bites[0]);
}

[Fact]
public void SpokenWithGestures_LiftsCyrillicToo()
{
    var said = SpeakableText.SpokenWithGestures("*навежда се към огъня* Седни.");
    Assert.StartsWith("Навежда", said);
}

[Fact]
public void IsWorthSpeaking_ATurningAwayIsWorthItWhenTheActsAreRead()
{
    Assert.False(SpeakableText.IsWorthSpeaking("*turns away without a word*"));
    Assert.True(SpeakableText.IsWorthSpeaking("*turns away without a word*", includeGestures: true));
}

[Fact]
public void Key_TellsTheTwoActedPartSettingsApart()
{
    const string withGesture = "Sit with me. *I pour the wine* It was a hard day.";
    Assert.NotEqual(
        VoiceCacheKey.For("sibylla", SpeakableText.SpokenOnly(withGesture)),
        VoiceCacheKey.For("sibylla", SpeakableText.SpokenWithGestures(withGesture)));

    const string plain = "Sit with me. It was a hard day.";
    Assert.Equal(
        VoiceCacheKey.For("sibylla", SpeakableText.SpokenOnly(plain)),
        VoiceCacheKey.For("sibylla", SpeakableText.SpokenWithGestures(plain)));
}

